import{_ as e,o as t,c as n,a6 as o}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"品牌KV、包装与广告入口","description":"","frontmatter":{"id":"brand","title":"品牌KV、包装与广告入口","chapter":"04","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":30,"content_kind":"任务入门"},"headers":[],"relativePath":"brand-content/brand.md","filePath":"brand-content/brand.md"}'),r={name:"brand-content/brand.md"};function s(i,a,d,p,l,c){return t(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="品牌kv、包装与广告-先做一张有明确用途的视觉稿" tabindex="-1">品牌KV、包装与广告，先做一张有明确用途的视觉稿 <a class="header-anchor" href="#品牌kv、包装与广告-先做一张有明确用途的视觉稿" aria-label="Permalink to &quot;品牌KV、包装与广告，先做一张有明确用途的视觉稿&quot;">​</a></h1><p>本节以果汁饮品上新KV为练习，做出无字视觉底图、可编辑标题和横竖两个版式。商品包装使用真实已确认素材；新包装概念可单独推演，不能当作已生产实物。完整包装结构、印刷和真实广告发布案例仍待补。</p><h2 id="_1-先确定一个传播任务" tabindex="-1">1. 先确定一个传播任务 <a class="header-anchor" href="#_1-先确定一个传播任务" aria-label="Permalink to &quot;1. 先确定一个传播任务&quot;">​</a></h2><p>在简报写品牌已有颜色、真实商品、目标受众、渠道、画幅和一句主信息。比如“办公室水果饮品”，主视觉可以是商品和水果场景，避免同时堆“健康、减脂、美容、提神”等没有商品依据的功效。</p><p>把Logo、包装、字体与图片素材的可用范围写清楚。产品图负责身份，参考广告只借构图与光线。包装上的实际字与结构不交给模型自由重画。</p><h2 id="_2-做无字底图" tabindex="-1">2. 做无字底图 <a class="header-anchor" href="#_2-做无字底图" aria-label="Permalink to &quot;2. 做无字底图&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>制作果汁饮品上新视觉底图。上传商品包装是唯一商品外观依据，保留瓶型、盖子、标签位置、颜色和比例。明亮浅色办公桌，柔和左侧窗光，少量真实水果作为场景元素，商品是主角。</span></span>
<span class="line"><span>竖向构图，顶部留简洁标题区，下方留小块行动信息区域。不生成文字、Logo、按钮、认证、功效符号和水印，不添加虚构配件。包装被改写时只生成空场景，真实商品和Logo后期合成。</span></span></code></pre></div><p>用支持参考图的设计画布输入任务，先做一个方向，再检查商品与包装。具体工具入口见<a href="./../workflows/canvases">三类画布</a>。结果只负责场景和布局，准确品牌文字用图层排版。</p><h2 id="_3-排主标题与行动信息" tabindex="-1">3. 排主标题与行动信息 <a class="header-anchor" href="#_3-排主标题与行动信息" aria-label="Permalink to &quot;3. 排主标题与行动信息&quot;">​</a></h2><p>在PS/Photopea分商品、背景、Logo、标题和行动信息五组。标题只保留一个主信息，行动信息写真实活动或链接用途。商品标签原文字模糊时换清晰实拍，别在模糊像素上补看起来像字的纹理。</p><p>竖版用于相应社交或展示位置；横版重新摆主体和标题，不能直接裁掉瓶盖。缩到手机宽度检查商品辨认、标题和行动信息。这个过程可复用<a href="./../prompts/P02">P02品牌KV模板</a>。</p><h2 id="_4-包装概念与实物展示分别交付" tabindex="-1">4. 包装概念与实物展示分别交付 <a class="header-anchor" href="#_4-包装概念与实物展示分别交付" aria-label="Permalink to &quot;4. 包装概念与实物展示分别交付&quot;">​</a></h2><p>新包装设计推演可探索配色、标签排布和使用场景，文件标“概念稿”。印刷刀模、出血、专色、条码、材料和工艺需要设计与供应商真实确认。营销图里呈现的发货包装必须来自实际版本，不能用概念稿替代。</p><p>本节是任务入门与操作方案，未生成KV、制作印刷文件或发布广告。</p>`,14)])])}const b=e(r,[["render",s]]);export{_ as __pageData,b as default};
